import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

matvec_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void matvec_kernel(const float* __restrict__ A,
                               const float* __restrict__ B,
                               float* __restrict__ C,
                               int M, int K, int splitK, int K4perSplit) {
    int row = blockIdx.y;
    int split = blockIdx.x;
    if (row >= M || split >= splitK) return;
    int K4 = K / 4;
    int startIdx4 = split * K4perSplit;
    int endIdx4 = startIdx4 + K4perSplit;
    if (endIdx4 > K4) endIdx4 = K4;
    const float4* A4 = reinterpret_cast<const float4*>(A + (size_t)row * K);
    const float4* B4 = reinterpret_cast<const float4*>(B);
    float sum = 0.0f;
    for (int i = startIdx4 + threadIdx.x; i < endIdx4; i += blockDim.x) {
        float4 a = A4[i];
        float4 b = B4[i];
        sum += a.x * b.x + a.y * b.y + a.z * b.z + a.w * b.w;
    }
    // handle remainder floats (K not divisible by 4) only in the last split
    if (split == splitK - 1) {
        int rem_start = K4 * 4;
        for (int i = rem_start + threadIdx.x; i < K; i += blockDim.x) {
            sum += A[(size_t)row * K + i] * B[i];
        }
    }
    // warp-level reduction
    unsigned mask = 0xffffffff;
    for (int offset = warpSize / 2; offset > 0; offset >>= 1)
        sum += __shfl_down_sync(mask, sum, offset);
    __shared__ float shared[32];
    int lane = threadIdx.x % warpSize;
    int wid = threadIdx.x / warpSize;
    if (lane == 0) shared[wid] = sum;
    __syncthreads();
    int numWarps = (blockDim.x + warpSize - 1) / warpSize;
    if (wid == 0) {
        sum = (lane < numWarps) ? shared[lane] : 0.0f;
        for (int offset = warpSize / 2; offset > 0; offset >>= 1)
            sum += __shfl_down_sync(mask, sum, offset);
        if (lane == 0) atomicAdd(&C[row], sum);
    }
}
torch::Tensor matvec_cuda(torch::Tensor A, torch::Tensor B) {
    A = A.contiguous();
    B = B.contiguous();
    int M = A.size(0);
    int K = A.size(1);
    auto C = torch::zeros({M, 1}, A.options());
    const int threads = 256;
    const int splitK = 8;
    int K4 = K / 4;
    int K4perSplit = (K4 + splitK - 1) / splitK;
    if (K4perSplit < 1) K4perSplit = 1;
    dim3 grid(splitK, M);
    matvec_kernel<<<grid, threads>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        M, K, splitK, K4perSplit
    );
    return C;
}
"""

matvec_cpp_source = r"""
torch::Tensor matvec_cuda(torch::Tensor A, torch::Tensor B);
"""

matvec_module = load_inline(
    name="matvec_module",
    cpp_sources=matvec_cpp_source,
    cuda_sources=matvec_source,
    functions=["matvec_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Optimized model that performs matrix-vector multiplication (C = A * B)
    using a custom CUDA kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self.matvec = matvec_module

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        A = A.cuda().float()
        B = B.cuda().float()
        return self.matvec.matvec_cuda(A, B)


M = 256 * 8  # 2048
K = 131072 * 8  # 1048576


def get_inputs():
    A = torch.rand(M, K)
    B = torch.rand(K, 1)
    return [A, B]


def get_init_inputs():
    return []

